const items = $input.first().json.data.children;
const results = [];

const bannedKeywords = ['suicide', 'self harm', 'gore', 'porn', 'explicit sex', 'nude', 'underage'];

for (const post of items) {
  const p = post.data;
  if (p.over_18 || p.is_video) continue;

  const titleLower = p.title.toLowerCase();
  const isBanned = bannedKeywords.some(w => titleLower.includes(w));
  if (isBanned) continue;

  if (p.score > 100) {
    results.push({
      json: {
        source: 'Reddit /r/Fauxmoi',
        source_title: p.title,
        source_url: 'https://reddit.com' + p.permalink,
        score: p.score,
        author: p.author,
        selftext: p.selftext || '',
        timestamp: p.created_utc
      }
    });
  }
}

return results.slice(0, 1);

const raw = $input.first().json;
const contentString = raw.choices[0].message.content;
const articleData = JSON.parse(contentString);

// Fallback safety validations
if (!articleData.slug) {
  articleData.slug = articleData.title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
}

articleData.published_at = new Date().toISOString();
articleData.hero_image = 'https://images.unsplash.com/photo-1514525253161-7a46d19cd819?w=1200&h=628&fit=crop'; // Default high-res fallback

return [{ json: articleData }];
